svg.script:
(function(){
  var arc = document.getElementById('arc');
  var pct = document.getElementById('pct');
  var ARC_LEN = 2 * Math.PI * 24;
  var win = (typeof window !== 'undefined' && window.parent && window.parent !== window) ? window.parent : window;
  var doc = win.document.documentElement;
  var raf = null;
  function update(){
    var y = win.scrollY || 0;
    var max = Math.max(1, doc.scrollHeight - win.innerHeight);
    var p = Math.min(100, Math.max(0, Math.round((y / max) * 100)));
    arc.style.strokeDashoffset = (ARC_LEN - (p / 100) * ARC_LEN).toString();
    pct.textContent = p + '%';
  }
  win.addEventListener('scroll', function(){
    if (raf) cancelAnimationFrame(raf);
    raf = requestAnimationFrame(update);
  }, { passive: true });
  update();
})();
